INSERT INTO eras (id, name, order_index, type, importance, description, created_at, updated_at, language, translation_group_id) VALUES ('2f0b14b1-2db2-4b78-a15b-d91b9344c26b', 'Era of Matter', 19, 'ERA', NULL, 'First semi-material beings shaped by the first particles.', '2026-06-23 18:54:04.75899+00', '2026-06-23 18:54:04.75899+00', 'en', '2f0b14b1-2db2-4b78-a15b-d91b9344c26b');
