INSERT INTO eras (id, name, order_index, type, importance, description, created_at, updated_at, language, translation_group_id) VALUES ('1cef56ea-c063-423d-8116-02abd1b4ee17', 'Era of Elements', 23, 'ERA', NULL, 'Different planets with different natures, each representing different forces of nature.', '2026-06-23 18:54:04.812994+00', '2026-06-23 18:54:04.812994+00', 'en', '1cef56ea-c063-423d-8116-02abd1b4ee17');
INSERT INTO eras (id, name, order_index, type, importance, description, created_at, updated_at, language, translation_group_id) VALUES ('a677296c-c0df-4012-a186-db612a55e39b', 'Emergence of Amphibians, Reptiles and Birds', 24, 'POINT', 'STANDARD', NULL, '2026-06-23 18:54:04.827346+00', '2026-06-23 18:54:04.827346+00', 'en', 'a677296c-c0df-4012-a186-db612a55e39b');
INSERT INTO eras (id, name, order_index, type, importance, description, created_at, updated_at, language, translation_group_id) VALUES ('4a645394-65ca-4cba-a559-93762db9122a', 'Era of Footprints', 25, 'ERA', NULL, 'Change of environment and the emergence of dragons.', '2026-06-23 18:54:04.841227+00', '2026-06-23 18:54:04.841227+00', 'en', '4a645394-65ca-4cba-a559-93762db9122a');
