INSERT INTO eras (id, name, order_index, type, importance, description, created_at, updated_at, language, translation_group_id) VALUES ('a5218652-50e5-4a59-8730-befe8589d2cf', 'Era of Wrath', 27, 'ERA', NULL, 'Continuation of the evolution of nature''s species.', '2026-06-23 18:54:04.868021+00', '2026-06-23 18:54:04.868021+00', 'en', 'a5218652-50e5-4a59-8730-befe8589d2cf');
