INSERT INTO eras (id, name, order_index, type, importance, description, created_at, updated_at, language, translation_group_id) VALUES ('79f695b4-dd5d-468c-8040-8dd8acecd700', 'Era of the Pristine', 29, 'ERA', NULL, 'The world comes to be dominated by semi-divine beings.', '2026-06-23 18:54:05.083278+00', '2026-06-23 18:54:05.083278+00', 'en', '79f695b4-dd5d-468c-8040-8dd8acecd700');
