INSERT INTO eras (id, name, order_index, type, importance, description, created_at, updated_at, language, translation_group_id) VALUES ('1096732a-5c98-48b1-85af-25f5e70580e6', 'Era of War', 33, 'ERA', NULL, 'The first nomadic peoples begin to unite and confront one another in a great war.', '2026-06-23 18:54:05.13198+00', '2026-06-23 18:54:05.13198+00', 'en', '1096732a-5c98-48b1-85af-25f5e70580e6');
