INSERT INTO eras (id, name, order_index, type, importance, description, created_at, updated_at, language, translation_group_id) VALUES ('a315a026-5488-4823-a1e6-b6c1c20238d8', 'Reopening of the Cosmic Rifts', 38, 'POINT', 'STANDARD', NULL, '2026-06-23 18:54:05.19475+00', '2026-06-23 18:54:05.19475+00', 'en', 'a315a026-5488-4823-a1e6-b6c1c20238d8');
INSERT INTO eras (id, name, order_index, type, importance, description, created_at, updated_at, language, translation_group_id) VALUES ('b33d7a47-cf46-4aa1-a6c5-b7527ec0de37', 'Era of Enlightenment', 39, 'ERA', NULL, 'The world begins to perceive the dangers of magic. Inquisition movements and technological research emerge.', '2026-06-23 18:54:05.206857+00', '2026-06-23 18:54:05.206857+00', 'en', 'b33d7a47-cf46-4aa1-a6c5-b7527ec0de37');
