INSERT INTO eras (id, name, order_index, type, importance, description, created_at, updated_at, language, translation_group_id) VALUES ('d96d7190-b5cd-415b-95c5-fe42b28bf2b7', 'Establishment of the New Technological Order', 42, 'POINT', 'STANDARD', NULL, '2026-06-23 18:54:05.6372+00', '2026-06-23 18:54:05.6372+00', 'en', 'd96d7190-b5cd-415b-95c5-fe42b28bf2b7');
