INSERT INTO eras (id, name, order_index, type, importance, description, created_at, updated_at, language, translation_group_id) VALUES ('fe965866-a03a-4287-b4a8-b6d9eac9acb8', 'Era of Technology', 45, 'ERA', NULL, 'The world becomes completely dominated by technology.', '2026-06-23 18:54:05.683915+00', '2026-06-23 18:54:05.683915+00', 'en', 'fe965866-a03a-4287-b4a8-b6d9eac9acb8');
