INSERT INTO eras (id, name, order_index, type, importance, description, created_at, updated_at, language, translation_group_id) VALUES ('48ed4b49-b7b5-4d4b-9715-00dcaa819209', 'Primordial Era', 1, 'ERA', NULL, 'The age before the material world came into being — a time of pure essence, divine forces, and the foundation upon which all existence would be built. No navigable world exists here; only the infinite.', '2026-06-23 18:54:04.047617+00', '2026-06-24 02:31:11.341815+00', 'en', '48ed4b49-b7b5-4d4b-9715-00dcaa819209');
