INSERT INTO eras (id, name, order_index, type, importance, description, created_at, updated_at, language, translation_group_id) VALUES ('eb903d2d-12a2-4e2b-9659-6d2243a8a70f', 'Era dos Vestígios', 3, 'ERA', NULL, 'A era mais antiga do mundo temporal, anterior à criação da matéria. Num universo ainda inexistente, vestígios de um mundo anterior flutuam à deriva, prontos para uma nova história.', '2026-06-23 18:54:04.13818+00', '2026-06-23 18:54:04.13818+00', 'pt', '49187d39-6121-44b9-8477-f19e16fac16b');
