INSERT INTO eras (id, name, order_index, type, importance, description, created_at, updated_at, language, translation_group_id) VALUES ('6f12e68d-ad71-4c51-8e80-942f8191fdda', 'Era dos Vislumbres', 5, 'ERA', NULL, 'Sob uma montanha, emergem os primeiros conceitos.', '2026-06-23 18:54:04.164302+00', '2026-06-23 18:54:04.164302+00', 'pt', '47eb040e-b0d3-492a-8817-525a91705240');
