INSERT INTO eras (id, name, order_index, type, importance, description, created_at, updated_at, language, translation_group_id) VALUES ('b0666803-2368-4aa2-b8b9-d009f73af809', 'Era do Impronunciável', 7, 'ERA', NULL, 'Os conceitos começam a tomar forma; diferentes povos se espalham sob a terra. Uma era definida pelo conflito entre individuação e união.', '2026-06-23 18:54:04.38277+00', '2026-06-23 18:54:04.38277+00', 'pt', '733fa7c5-700d-418e-bcdd-64afe020bf3f');
